head.script:
scwin.screenId = "jldfil71203";

///////// 1. 변수 및 선언 영역 /////////

scwin.daily = $c.util.getComponent('daily');

scwin.sometimes = $c.util.getComponent('sometimes');

scwin.if_3or4 = $c.util.getComponent('if_3or4');

scwin.earyNum = 1;

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.form = undefined;


///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "txa_expEarngStructDscVal", attr: "label", fn: function () { return String(dma_readDataVO.get("expEarngStructDscVal")); } },
        { childId: "__rb7", attr: "label", fn: function () { return String(dma_readDataVO.get("valuPrc1HistVoltPd")) + " 개월"; } },
        { childId: "__rb8", attr: "label", fn: function () { return String(dma_readDataVO.get("valuPrc2HistVoltPd")) + " 개월"; } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_65", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702' || (dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'); } }, { id: "tr_66", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702' || (dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'); } }, { id: "c_otherwise_71", fn: function(){ return (!(((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702' || (dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(dma_readDataVO.get("expMaxYd")) + " (%)"; } },
        { childId: "__rb1", fn: function () { return String(dma_readDataVO.get("expMaxRedmptPrc")) + " (원)"; } },
        { childId: "__rb2", fn: function () { return String(dma_readDataVO.get("expMaxLossRt")) + " (%)"; } },
        { childId: "__rb3", fn: function () { return String(dma_readDataVO.get("expMinRedmptPrc")) + " (원)"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.earyRedmptCondYn();
        scwin.earyRedmptCondRelCd();
        scwin.insertComma(2);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71203.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil71203: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.earyRedmptValuDdList = undefined; try { scwin.earyRedmptValuDdList = /* sdd-asis-lifecycle:begin earyRedmptValuDdList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil71203' }); }

scwin.earyRedmptBas1IdxList = undefined; try { scwin.earyRedmptBas1IdxList = /* sdd-asis-lifecycle:begin earyRedmptBas1IdxList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil71203' }); }

scwin.earyRedmptBas2IdxList = undefined; try { scwin.earyRedmptBas2IdxList = /* sdd-asis-lifecycle:begin earyRedmptBas2IdxList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil71203' }); }

scwin.earyRedmptPrcList = undefined; try { scwin.earyRedmptPrcList = /* sdd-asis-lifecycle:begin earyRedmptPrcList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil71203' }); }

scwin.earyRedmptPayDdList = undefined; try { scwin.earyRedmptPayDdList = /* sdd-asis-lifecycle:begin earyRedmptPayDdList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil71203' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil71203.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
