///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.etnChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param tab
 * @returns
 * @hidden N
*/
scwin.etnChangePage = async function (tab) {
    /* sdd-asis-lifecycle:begin fn_EtnChangePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.etnListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent("dma_EtnChangePageReq").get("lastSaveStatCd"));
    if (tab == 1) {
        $c.util.getComponent("dma_EtnChangePageReq").set("method", 'lossLimitViewIsuTab');
    } else {
        if (tab == 2) {
            return;
        } else {
            if (tab == 3) {
                $c.util.getComponent("dma_EtnChangePageReq").set("method", 'lossLimitViewIsurTab');
            } else {
                if (tab == 4) {
                    $c.util.getComponent("dma_EtnChangePageReq").set("method", 'lossLimitViewSrtyLpTab');
                } else {
                    $c.util.getComponent("dma_EtnChangePageReq").set("method", 'lossLimitViewAttachFileTab');
                }
            }
        }
    }
    scwin.form.action = 'LossLimitEtnList.do';
    await scwin.tx_fn_EtnChangePage();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = "EtnList.do";
    $c.util.getComponent("dma_EtnChangePageReq").set("listBzTpCd", "");
    $c.util.getComponent("dma_EtnChangePageReq").set("method", 'searchList');
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.earyRedmptCondYn
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.earyRedmptCondYn = function () {
    /* sdd-asis-lifecycle:begin fn_earyRedmptCondYn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let obj = $c.util.getComponent('slc_earyRedmptCondYn').getValue(); if (obj == null) { obj = ''; }
    if (obj === 'N') {
        $c.util.getComponent('slc_earyRedmptCycleCd').setValue("");
        (($c.util.getComponent('slc_earyRedmptCycleCd')) && ($c.util.getComponent('slc_earyRedmptCycleCd')).setDisabled ? ($c.util.getComponent('slc_earyRedmptCycleCd')).setDisabled(('true') === 'disabled' || ('true') === 'readonly' || ('true') === 'checked' ? true : ('true')) : void 0);
    } else {

    }
    scwin.earyRedmptCycleCd();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.earyRedmptCycleCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.earyRedmptCycleCd = function () {
    /* sdd-asis-lifecycle:begin fn_earyRedmptCycleCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let obj = $c.util.getComponent('slc_earyRedmptCycleCd').getValue(); if (obj == null) { obj = ''; }
    if (obj === '') {
        scwin.daily.setStyle("display", "none");
        scwin.sometimes.setStyle("display", "none");
    } else {
        if (obj === '01') {
            scwin.daily.setStyle("display", "");
            scwin.sometimes.setStyle("display", "none");
        } else {
            scwin.daily.setStyle("display", "none");
            scwin.sometimes.setStyle("display", "");
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.addEaryRedmptCond
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.addEaryRedmptCond = function () {
    /* sdd-asis-lifecycle:begin addEaryRedmptCond — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const earyCondRelCd = $c.util.getComponent('slc_earyRedmptCondRelCd').getValue();
    let sgnVal1, sgnVal2;
    if (earyCondRelCd === '1') {
        sgnVal1 = '<option value="1">이상</option>';
    } else {
        if (earyCondRelCd === '2') {
            sgnVal1 = '<option value="1">이하</option>';
        } else {
            if (earyCondRelCd === '3') {
                sgnVal1 = '<option value="1">이상</option>';
                sgnVal2 = '<option value="2">이하</option>';
            } else {
                if (earyCondRelCd === '4') {
                    sgnVal1 = '<option value="2">이하</option>';
                    sgnVal2 = '<option value="1">이상</option>';
                }
            }
        }
    }
    scwin.earyNum++;
    const language = $c.util.getComponent("earyRedptCond1");
    let txt = '		<div style="border-top: solid 1px; padding: 10px;">';
    txt += '			<div style="padding-bottom:5px;">';
    txt += '				<b>' + scwin.earyNum + '차</b>';
    txt += '				<span style="padding-left:5px;">';
    txt += '					조기상환 평가일 <input type="text" name="earyRedmptValuDd" id="earyRedmptValuDd' + scwin.earyNum + '" value="" class="form_search" size="10"  maxlength="8" alt="조기상환평가일" disabled="disabled" />';
    txt += '				</span>';
    txt += '			</div>';
    txt += '			<div style="padding-left:26px;padding-bottom:5px;">';
    txt += '				<span>조기상환 기준</span>';
    txt += '				<span style="padding-left:16px;">';
    txt += '					기초지수가 ';
    txt += '					<input type="text" name="earyRedmptBas1Idx" id="earyRedmptBas1Idx" value="" class="form_search_money" size="10" disabled="disabled" />';
    txt += '					<select name="sgn1" id="sgn1" class="form_select" disabled="disabled">' + sgnVal1 + '</select> ';
    if (earyCondRelCd === '3') {
        txt += '					<span id="if_3">또는 </span>';
    }
    if (earyCondRelCd === '4') {
        txt += '					<span id="if_4">이면서 </span>';
    }
    if (earyCondRelCd === '3' || earyCondRelCd === '4') {
        txt += '					<span id="if_3or4">';
        txt += '						<input type="text" name="earyRedmptBas2Idx" id="earyRedmptBas2Idx" value="" class="form_search_money" size="10" disabled="disabled" />';
        txt += '						<select name="sgn2" id="sgn2" class="form_select" disabled="disabled">' + sgnVal2 + '</select>';
        txt += '					</span>	';
    }
    txt += '					인 경우';
    txt += '				</span>';
    txt += '			</div>';
    txt += '			<div style="padding-left:26px;">';
    txt += '				조기상환가격(제비용 차감전) <input type="text" name="earyRedmptPrc" id="earyRedmptPrc" value="" class="form_search_money" size="10" disabled="disabled" />(원)';
