/**
 * @method
 * @name scwin.earyRedmptCondRelCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.earyRedmptCondRelCd = function () {
    /* sdd-asis-lifecycle:begin fn_earyRedmptCondRelCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let obj = $c.util.getComponent('slc_earyRedmptCondRelCd').getValue(); if (obj == null) { obj = ''; }
    if (obj === '1') {
        $c.util.getComponent('if_3').setStyle("display", "none");
        $c.util.getComponent('if_4').setStyle("display", "none");
        scwin.if_3or4.setStyle("display", "none");
        $('#slc_sgn1 option').remove();
        $('#slc_sgn2 option').remove();
        $c.util.getComponent('slc_sgn1').addItem("1", "이상");
    } else {
        if (obj === '2') {
            $c.util.getComponent('if_3').setStyle("display", "none");
            $c.util.getComponent('if_4').setStyle("display", "none");
            scwin.if_3or4.setStyle("display", "none");
            $('#slc_sgn1 option').remove();
            $('#slc_sgn2 option').remove();
            $c.util.getComponent('slc_sgn1').addItem("2", "이하");
        } else {
            if (obj === '3') {
                $c.util.getComponent('if_3').setStyle("display", "");
                $c.util.getComponent('if_4').setStyle("display", "none");
                scwin.if_3or4.setStyle("display", "");
                $('#slc_sgn1 option').remove();
                $('#slc_sgn2 option').remove();
                $c.util.getComponent('slc_sgn1').addItem("1", "이상");
                $c.util.getComponent('slc_sgn2').addItem("2", "이하");
            } else {
                if (obj === '4') {
                    $c.util.getComponent('if_3').setStyle("display", "none");
                    $c.util.getComponent('if_4').setStyle("display", "");
                    scwin.if_3or4.setStyle("display", "");
                    $('#slc_sgn1 option').remove();
                    $('#slc_sgn2 option').remove();
                    $c.util.getComponent('slc_sgn1').addItem("2", "이하");
                    $c.util.getComponent('slc_sgn2').addItem("1", "이상");
                }
            }
        }
    }
    if (obj === $) {
        earyRedmptCondRelCdSet;
    }
    scwin.setEaryRedmpt();
    /* sdd-asis-lifecycle:end */
};


